        typeof provider.replyToThread !== 'function' ||
        typeof provider.resolveThread !== 'function') {
        console.warn('  ⚠️ resolveSuggestionThreads: provider lacks the verdict/thread primitives — skipped (gitlab twin has none yet)');
        return none;
