    test('#1428 replay: contradictory verdicts one head → loser pr_approved comes off with a both-sources comment', function () {
        var sm = makeSmAgent({
            fileMap: { '../.dmtools/config.js': 'module.exports = { repository: { owner: "epam", repo: "dmtools-dart" } };' },
            github: {
