    test('APPROVE winner → agent:rework comes off BOTH carriers', function () {
        var sm = makeSmAgent({
            fileMap: { '../.dmtools/config.js': 'module.exports = { repository: { owner: "epam", repo: "dmtools-dart" } };' },
