                items: [
                    { key: 'pr-1428', labels: ['ai_pr_reviewed'], issueNumber: null, prNumber: 1428 }
                ],
                pr: { number: 1428, head: { sha: HEAD }, labels: ['ai_pr_reviewed'] },
                prComments: []
            }
        });

        sm.action(baseParams('epam', 'dmtools-dart', [armRule()]));

