    var memoId = String(prNumber);
    if (allow) {
        memoId += '|aw:' + allow.map(function (l) { return String(l || '').toLowerCase(); })
            .sort().join(',');
    }
    var memo = ioCacheGet(owner, repo, 'prVerdicts', memoId);
    if (memo) return memo;
    ...
    records = reviewVerdicts.parseVerdictRecords(list, allow ? { authorLogins: allow } : undefined);
