        // unauthenticated APPROVE/REQUEST_CHANGES must be invisible). The
        // memo key carries the allowlist so a filtered read never poisons
        // the unfiltered entry (and vice versa). Probe failure fails OPEN
        // (empty list → guards inert → legacy behavior): a broken comment
        // read must never strand a PR.
        verdictRecords: function (prNumber, opts) {
            var allow = (opts && Array.isArray(opts.authorLogins)) ? opts.authorLogins : null;
            var memoId = String(prNumber);
            if (allow) {
                memoId += '|aw:' + allow.map(function (l) {
                    return String(l || '').toLowerCase();
                }).sort().join(',');
